using Unity.Mathematics;
using UnityEditor;
using UnityEngine;
using ZE.MechBattle;
using ZE.MechBattle.Projectiles;
using ZE.MechBattle.Weapons;


//generated by Deepseek, checked by Qwen
public class TrajectorySegmentsWizard : ScriptableWizard
{
    [Header("Points")]
    public float3 startPoint = new (0f, 0f, -120f);
    public float3 endPoint = new(-120f, 0f, -120f);

    [Header("Projectile")]
    public float speed = 60f;

    [Header("Visualization")]
    [Tooltip("Длина одного фрагмента отрисовки параболы (м)")]
    public float fragmentLength = 10f;

    [Header("Segments")]
    public float slopeThreshold = 0.2f;
    public float pad = 0.05f;


    private bool _hasResult;
    private float3[] _arcPoints;
    private HighArcRaycastSegments _segments;

    [MenuItem("Tools/Trajectory Segments Wizard")]
    static void Open()
    {
        DisplayWizard<TrajectorySegmentsWizard>(
            "Trajectory Segments", "Exit", "Draw");
    }

    void OnWizardOtherButton() // кнопка "Draw" (primary button)
    {
        _hasResult = false;
        var gravity = -Physics.gravity.y;

        // 1. Наводка
        if (!HighAngleTrajectorySolver.TryExecute(startPoint, endPoint, speed, gravity,
                                        out float3 normalizedDirection, out float tFlight))
        {
            Debug.LogWarning("TrajectorySegmentsWizard: цель недосягаема при заданной скорости.");
            SceneView.RepaintAll();
            return;
        }

        var projectileMoveVector = speed * normalizedDirection;        

        // 2. Доли разбиения
        var segments = HighAngleTrajectoryPartitioningLogic.CalculatePartitions(
            projectileMoveVector, gravity, tFlight, slopeThreshold);

        UnityEngine.Debug.Log($"flight time: {tFlight}");

        // 3. Три отрезка
        _segments = HighAngleTrajectoryRaycastPointsDefineLogic.BuildThreeSegments(
            startPoint, projectileMoveVector, gravity, tFlight, segments.x, segments.y, pad);

        //UnityEngine.Debug.Log($"{segments.x} {segments.y}");

        // 4. Детализированная парабола по длине фрагмента.
        _arcPoints = BuildArc(startPoint, projectileMoveVector, gravity, tFlight, fragmentLength);

        _hasResult = true;
        SceneView.RepaintAll();
    }

    void OnWizardCreate()
    {
        _hasResult = false;
        _arcPoints = null;
        SceneView.RepaintAll();
    }

    void OnEnable()
    {
        SceneView.duringSceneGui += OnSceneGUI;
    }

    void OnDisable()
    {
        SceneView.duringSceneGui -= OnSceneGUI;
    }

    void OnSceneGUI(SceneView sceneView)
    {
        if (!_hasResult) return;

        // parabola draw
        if (_arcPoints != null && _arcPoints.Length > 1)
        {
            Handles.color = Color.white;
            for (int i = 1; i < _arcPoints.Length; i++)
                Handles.DrawLine(_arcPoints[i - 1], _arcPoints[i]);
        }

        // segments draw
        Handles.color = Color.yellow;
        Handles.DrawLine(_segments.StartSegment.Start, _segments.StartSegment.End);
        Handles.DrawLine(_segments.MiddleSegment.Start, _segments.MiddleSegment.End);
        Handles.DrawLine(_segments.EndSegment.Start, _segments.EndSegment.End);

        // Точки старта/цели.
        Handles.color = Color.green;
        Handles.DrawSolidDisc(startPoint, -sceneView.camera.transform.forward, 0.15f);
        Handles.color = Color.red;
        Handles.DrawSolidDisc(endPoint, -sceneView.camera.transform.forward, 0.15f);
    }

    // Разбиение параболы по длине фрагмента (вдоль дуги, а не по времени).
    static float3[] BuildArc(float3 p0, float3 v0, float g, float tTotal, float fragLen)
    {
        float3 gVec = new float3(0f, -g, 0f);
        float3 P(float t) => p0 + v0 * t + 0.5f * gVec * t * t;

        // Оцениваем полную длину дуги грубо, чтобы задать число шагов.
        const int roughSteps = 64;
        float roughLen = 0f;
        float3 prev = P(0f);
        for (int i = 1; i <= roughSteps; i++)
        {
            float3 cur = P(tTotal * i / roughSteps);
            roughLen += math.distance(prev, cur);
            prev = cur;
        }

        int steps = math.max(2, (int)math.ceil(roughLen / Mathf.Max(0.01f, fragLen)) + 1);

        var pts = new float3[steps];
        for (int i = 0; i < steps; i++)
            pts[i] = P(tTotal * i / (steps - 1));
        return pts;
    }
}
